import{_ as t,o as a,c as r,a3 as d}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"AIHubMix","description":"AIHubMix 無料モデルゲートウェイ：公式入口、*-free テキストと画像一覧、Key 取得、MiniTavern での記入。","frontmatter":{"title":"AIHubMix","description":"AIHubMix 無料モデルゲートウェイ：公式入口、*-free テキストと画像一覧、Key 取得、MiniTavern での記入。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"AIHubMix · MiniTavern Docs"}],["meta",{"property":"og:description","content":"AIHubMix 無料モデルゲートウェイ：公式入口、*-free テキストと画像一覧、Key 取得、MiniTavern での記入。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/free-cloud/aihubmix"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/free-cloud/aihubmix"}]]},"headers":[],"relativePath":"ja/free-cloud/aihubmix.md","filePath":"ja/free-cloud/aihubmix.md","lastUpdated":1787224147000}'),o={name:"ja/free-cloud/aihubmix.md"};function i(n,e,l,c,h,s){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h1><p>統一の <strong>OpenAI 互換</strong> API ゲートウェイで多数モデルを集約；うち <strong>27+ の <code>-free</code> 接尾辞モデル</strong>はプラットフォーム補助金で、モデル別枠内は無料呼び出し可（クレジットカード不要なことが多い）。1 つの Key で GPT／Gemini／GLM／Kimi などを比較し、無料生図も試せる。紹介：<a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">AIHubMix 上的免费 AI 模型</a>。</p><blockquote><p>枠、モデル名簿、「新規ユーザー贈与回数」は変わる。<strong><a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a> とコンソールを正</strong>とする。</p></blockquote><h2 id="公式と入口" tabindex="-1">公式と入口 <a class="header-anchor" href="#公式と入口" aria-label="Permalink to &quot;公式と入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>リソース</th><th>アドレス</th></tr></thead><tbody><tr><td>公式／登録</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a></td></tr><tr><td>無料モデル説明</td><td><a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">docs.aihubmix.com/cn/blogs/free-ai-models</a></td></tr><tr><td>モデル広場</td><td><a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a></td></tr><tr><td>開発者ドキュメント</td><td><a href="https://docs.aihubmix.com/cn" target="_blank" rel="noreferrer">docs.aihubmix.com/cn</a></td></tr><tr><td>API Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr></tbody></table><h2 id="無料の取得" tabindex="-1">無料の取得 <a class="header-anchor" href="#無料の取得" aria-label="Permalink to &quot;無料の取得&quot;">​</a></h2><ol><li><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> でメールまたは OAuth 登録（公式は <strong>クレジットカード不要</strong> と明記）。</li><li><strong>API Keys</strong> → Key 作成（よくある形式 <code>sk-…</code>）。</li><li>モデル広場で無料モデルを絞り、ID を控える（多くは <code>-free</code> 終わり）。</li><li>MiniTavern で <strong>カスタム (OpenAI)</strong>／<strong>カスタム (OpenAI Images)</strong> に Base URL と Key を記入。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td>無料方式</td><td>モデル ID が <code>-free</code>；<strong>RPM／日次 token</strong> などで限速、枠は日次リセット（各モデルページ参照）</td></tr><tr><td>新規ユーザー</td><td>文では登録後、一部無料モデルに有限回数が贈られるとある（GPT-5.5、GPT-Image-2 など）；チャージでさらに解放 — コンソール準拠</td></tr><tr><td>カード紐付け</td><td>無料帯は通常不要</td></tr><tr><td>OpenRouter との違い</td><td>OpenRouter 無料層は開源の広さ寄り；AIHubMix は補助金後の先端閉源 <code>*-free</code>（GPT／Gemini 無料ミラーなど）を強調</td></tr></tbody></table><h2 id="モデル一覧" tabindex="-1">モデル一覧 <a class="header-anchor" href="#モデル一覧" aria-label="Permalink to &quot;モデル一覧&quot;">​</a></h2><p>公式無料モデル文からの抜粋（約 2026-05）；<strong>実態はモデル広場準拠</strong>。ID は <strong>大文字小文字区別</strong>。</p><h3 id="テキスト-対話-推論" tabindex="-1">テキスト（対話／推論） <a class="header-anchor" href="#テキスト-対話-推論" aria-label="Permalink to &quot;テキスト（対話／推論）&quot;">​</a></h3><p>Chat Completions。MiniTavern は <strong>カスタム (OpenAI)</strong>。</p><h4 id="汎用対話" tabindex="-1">汎用対話 <a class="header-anchor" href="#汎用対話" aria-label="Permalink to &quot;汎用対話&quot;">​</a></h4><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>gpt-5.5-free</code></td><td>旗艦対話／Agent／コード（プラットフォーム補助金）</td></tr><tr><td><code>gpt-4o-free</code></td><td>マルチモーダル視覚</td></tr><tr><td><code>gpt-4.1-free</code></td><td>長コンテキスト（約 1M）</td></tr><tr><td><code>gpt-4.1-mini-free</code> / <code>gpt-4.1-nano-free</code></td><td>速度とコスト向け</td></tr><tr><td><code>gemini-3-flash-preview-free</code></td><td>超長コンテキスト、マルチモーダル</td></tr><tr><td><code>glm-4.7-flash-free</code></td><td>智譜 Flash</td></tr><tr><td><code>mimo-v2-flash-free</code> / <code>ling-2.6-flash-free</code></td><td>低遅延対話</td></tr></tbody></table><h4 id="コーディング向け" tabindex="-1">コーディング向け <a class="header-anchor" href="#コーディング向け" aria-label="Permalink to &quot;コーディング向け&quot;">​</a></h4><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>coding-glm-5.1-free</code></td><td>公式が重点推奨する無料コーディング帯</td></tr><tr><td><code>coding-glm-5-free</code> / <code>coding-glm-5-turbo-free</code> / <code>coding-glm-4.7-free</code> など</td><td>GLM コーディング系列</td></tr><tr><td><code>kimi-for-coding-free</code> / <code>k2.6-code-preview-free</code></td><td>Kimi コーディング</td></tr><tr><td><code>coding-minimax-m2-free</code> … <code>coding-minimax-m2.7-free</code></td><td>MiniMax コーディング系列</td></tr><tr><td><code>step-3.5-flash-free</code></td><td>軽量補完</td></tr></tbody></table><h4 id="agent-推論" tabindex="-1">Agent／推論 <a class="header-anchor" href="#agent-推論" aria-label="Permalink to &quot;Agent／推論&quot;">​</a></h4><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>xiaomi-mimo-v2-pro-free</code></td><td>ツール呼び出し／Agent</td></tr><tr><td><code>xiaomi-mimo-v2.5-free</code></td><td>より長いコンテキストと多ツール呼び出し</td></tr></tbody></table><p>ロールプレイチャットは先に <code>gpt-4o-free</code>、<code>gemini-3-flash-preview-free</code> または <code>glm-4.7-flash-free</code>；コーディング向けはコード補完寄りで、長劇情には向かないことがある。</p><h3 id="画像-文生図-編集" tabindex="-1">画像（文生図／編集） <a class="header-anchor" href="#画像-文生図-編集" aria-label="Permalink to &quot;画像（文生図／編集）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>モデル ID</th><th>インタフェースのヒント</th><th>App</th></tr></thead><tbody><tr><td><code>gpt-image-2-free</code></td><td><code>POST /v1/images/generations</code>（edits も可）</td><td><strong>カスタム (OpenAI Images)</strong></td></tr><tr><td><code>gemini-3.1-flash-image-preview-free</code>（Nano Banana 2）</td><td>公式は Chat Completions 対話生図可とする</td><td>画像接続は互換しない場合あり；Images エンドポイントを試すか <code>gpt-image-2-free</code> へ</td></tr></tbody></table><h3 id="動画" tabindex="-1">動画 <a class="header-anchor" href="#動画" aria-label="Permalink to &quot;動画&quot;">​</a></h3><p>公式の当該無料一覧は <strong>LLM＋画像</strong> 中心；動画能力があればモデル広場の表記準拠。MiniTavern に <strong>内蔵の動画生成入口はない</strong>。</p><h2 id="minitavern-での記入" tabindex="-1">MiniTavern での記入 <a class="header-anchor" href="#minitavern-での記入" aria-label="Permalink to &quot;MiniTavern での記入&quot;">​</a></h2><p>一般手順は <a href="/ultra_guides/ja/manual/model-link">モデル接続</a>。</p><h3 id="チャット" tabindex="-1">チャット <a class="header-anchor" href="#チャット" aria-label="Permalink to &quot;チャット&quot;">​</a></h3><p>経路：<strong>設定 → モデル → モデル接続 → 新規</strong></p><ol><li>プラットフォーム <strong>カスタム (OpenAI)</strong></li><li>Base URL：<code>https://aihubmix.com/v1</code></li><li>API Key を貼り付け</li><li>モデル ID に <code>gpt-4o-free</code> または広場の他 <code>*-free</code></li><li><strong>テスト</strong> → 成功後にデフォルトへ</li></ol><h3 id="画像生成" tabindex="-1">画像生成 <a class="header-anchor" href="#画像生成" aria-label="Permalink to &quot;画像生成&quot;">​</a></h3><p>経路：<strong>設定 → 画像生成 → 画像接続</strong></p><ol><li>プラットフォーム <strong>カスタム (OpenAI Images)</strong></li><li>Base URL 同上</li><li>同一 Key；モデルは <code>gpt-image-2-free</code></li><li>測連後に <code>/imagine</code> や画像入口で使用</li></ol><h2 id="関連章" tabindex="-1">関連章 <a class="header-anchor" href="#関連章" aria-label="Permalink to &quot;関連章&quot;">​</a></h2><ul><li><a href="/ultra_guides/ja/free-cloud/">無料クラウド総覧</a></li><li><a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料の画像生成</a></li><li><a href="/ultra_guides/ja/free-cloud/opencode-zen">OpenCode Zen</a> — コーディング向け精選ゲートウェイと別の Free テキスト</li><li><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/ja/free-cloud/openrouter">OpenRouter</a> — 開源 <code>:free</code> プール</li><li><a href="/ultra_guides/ja/manual/model-link">モデル接続</a></li></ul>',33)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
